export function getRandomNonVerbalQuizQuestions(): QuizQuestion[] {
  // Select 10 random questions from each of the 10 categories (10 x 10 = 100 questions)
  const selected: QuizQuestion[] = [];
  let orderIndex = 1;

  for (let catId = 1; catId <= 10; catId++) {
    const categoryQuestions = NON_VERBAL_500_BANK.filter(q => q.category_id === catId);
    // Shuffle and pick 10
    const shuffled = [...categoryQuestions].sort(() => 0.5 - Math.random());
    const picked = shuffled.slice(0, 10);

    picked.forEach(q => {
      selected.push({
        id: q.id,
        quiz_id: 2,
        category: q.category,
        question_text: q.question_text,
        option_a: q.option_a,
        option_b: q.option_b,
        option_c: q.option_c,
        option_d: q.option_d,
        correct_option: q.correct_option,
        explanation: q.explanation,
        question_image_url: q.question_image_url,
        option_a_image_url: q.option_a_image_url,
        option_b_image_url: q.option_b_image_url,
        option_c_image_url: q.option_c_image_url,
        option_d_image_url: q.option_d_image_url,
        order_index: orderIndex++
      });
    });
  }

  return selected;
}
